    // 1. Declare inputs as regs, outputs as wires
    // 2. Instantiate TopModule dut ( ... );
    // 3. Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Apply stimulus and verify outputs
        // If an output is wrong: errors = errors + 1;
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
```

SPECIFICATION:

I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  clk
 - input  reset
 - output ena (4 bits)
 - output q   (16 bits)

The module should implement a 4-digit BCD (binary-coded decimal) counter.
Each decimal digit is encoded using 4 bits: q[3:0] is the ones digit,
q[7:4] is the tens digit, etc. For digits [3:1], also output an enable
signal indicating when each of the upper three digits should be
incremented. Include a synchronous active-high reset. Assume all
sequential logic is triggered on the positive edge of the clock.



CANDIDATE RTL TO ATTACK:
```verilog
module TopModule (
    input        clk,
    input        reset,
    output [3:0] ena,
    output [15:0] q
);

    // Internal registers for the 4 BCD digits
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    // Enable signals for digits 1, 2, and 3 (tens, hundreds, thousands)
    wire ena_ones;
    wire ena_tens;
    wire ena_hundreds;
    wire ena_thousands;

    // The ones digit always increments on every clock cycle
    assign ena_ones      = 1'b1;
    assign ena_tens      = (ones == 4'd9);
    assign ena_hundreds  = (tens == 4'd9) && ena_tens;
    assign ena_thousands = (hundreds == 4'd9) && ena_hundreds;

    // Pack the enables into the 4-bit output 'ena'
    // ena[0]: ones enable (always 1)
    // ena[1]: tens enable
    // ena[2]: hundreds enable
    // ena[3]: thousands enable
    assign ena = {ena_thousands, ena_hundreds, ena_tens, ena_ones};

    // Pack the BCD digits into the 16-bit output 'q'
    // q[3:0]   = ones
    // q[7:4]   = tens
    // q[11:8]  = hundreds
    // q[15:12] = thousands
    assign q = {thousands, hundreds, tens, ones};

    always @(posedge clk) begin
        if (reset) begin
            ones      <= 4'd0;
            tens      <= 4'd0;
            hundreds  <= 4'd0;
            thousands <= 4'd0;
        end else begin
            // Ones digit
            if (ones == 4'd9)
                ones <= 4'd0;
            else
                ones <= ones + 4'd1;

            // Tens digit
            if (ena_tens) begin
                if (tens == 4'd9)
                    tens <= 4'd0;
                else
                    tens <= tens + 4'd1;
            end

            // Hundreds digit
            if (ena_hundreds) begin
                if (hundreds == 4'd9)
                    hundreds <= 4'd0;
                else
                    hundreds <= hundreds + 4'd1;
            end

            // Thousands digit
            if (ena_thousands) begin
                if (thousands == 4'd9)
                    thousands <= 4'd0;
                else
                    thousands <= thousands + 4'd1;
            end
        end
    end

endmodule
```

